    for (const auto& e : get_ellps_list()) {
        if (e.id == name) {
            a = e.a;
            if (e.has_rf) {
                rf = e.rf;
                double f = 1.0 / rf;
                b = a * (1.0 - f);
                is_sphere = (rf == 0 || std::isinf(rf));
            } else {
                b = e.b;
                rf = (a == b) ? 0 : a / (a - b);
                is_sphere = (a == b);
