#ifndef DMS_HPP
#define DMS_HPP

#include <string>
#include <cmath>
#include <cctype>
#include <cstdlib>
#include <iostream>
#include <sstream>
#include <iomanip>

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

#define DEG_TO_RAD (M_PI / 180.0)
#define RAD_TO_DEG (180.0 / M_PI)

inline double dmstof(const std::string& str, bool& ok) {
    ok = false;
    if (str.empty()) return 0.0;

    std::string s = str;
    // Trim leading/trailing whitespace
    size_t start = s.find_first_not_of(" \t\r\n");
    if (start == std::string::npos) return 0.0;
    size_t end = s.find_last_not_of(" \t\r\n");
    s = s.substr(start, end - start + 1);

    int sign = 1;
    if (s[0] == '-') {
        sign = -1;
        s = s.substr(1);
    } else if (s[0] == '+') {
        s = s.substr(1);
    }

    // Check for N, S, E, W suffix or prefix
    char dir = 0;
    if (!s.empty()) {
        char last = std::toupper((unsigned char)s.back());
        if (last == 'N' || last == 'E') {
            dir = last;
            s.pop_back();
        } else if (last == 'S' || last == 'W') {
            dir = last;
            s.pop_back();
            sign = -sign;
        }
    }

    double deg = 0.0, min = 0.0, sec = 0.0;
    bool parsed = false;

    // Check if 'd' or 'r' or '\'' or '\"' or ':' are in string
    size_t d_pos = s.find_first_of("dD");
    size_t r_pos = s.find_first_of("rR");
    if (r_pos != std::string::npos) {
        // Radians directly
        try {
            double rad = std::stod(s.substr(0, r_pos));
            ok = true;
            return rad * sign;
        } catch (...) {
            return 0.0;
        }
    }

    if (d_pos != std::string::npos) {
        try {
            std::string d_str = s.substr(0, d_pos);
            deg = d_str.empty() ? 0.0 : std::stod(d_str);
            std::string rem = s.substr(d_pos + 1);
            size_t m_pos = rem.find('\'');
            if (m_pos != std::string::npos) {
                std::string m_str = rem.substr(0, m_pos);
                min = m_str.empty() ? 0.0 : std::stod(m_str);
                std::string s_rem = rem.substr(m_pos + 1);
                size_t s_pos = s_rem.find('\"');
                if (s_pos != std::string::npos) {
                    std::string s_str = s_rem.substr(0, s_pos);
                    sec = s_str.empty() ? 0.0 : std::stod(s_str);
                } else if (!s_rem.empty()) {
                    sec = std::stod(s_rem);
                }
            } else if (!rem.empty()) {
                size_t s_pos = rem.find('\"');
                if (s_pos != std::string::npos) {
                    sec = std::stod(rem.substr(0, s_pos));
                } else {
                    min = std::stod(rem);
                }
            }
            parsed = true;
        } catch (...) {
            parsed = false;
        }
    } else {
        // Plain double or colon format
        try {
            char* endptr = nullptr;
            deg = std::strtod(s.c_str(), &endptr);
            if (endptr != s.c_str()) {
                parsed = true;
            }
        } catch (...) {
            parsed = false;
        }
    }

    if (parsed) {
        ok = true;
