#ifndef PROJ_MATH_HPP
#define PROJ_MATH_HPP

#include <string>
#include <cmath>
#include <vector>
#include <map>
#include <iostream>
#include <algorithm>
#include <sstream>
#include "dms.hpp"
#include "ellps.hpp"
#include "units.hpp"

#ifndef M_PI_4
#define M_PI_4 0.78539816339744830962
#endif

#ifndef M_PI_2
#define M_PI_2 1.57079632679489661923
#endif

struct ProjParams {
    std::string name;
    double a = 6378137.0;
    double b = 6356752.314245179;
    double rf = 298.257222101;
    double e2 = 0.006694380022900787;
    double e = 0.08181919084262149;
    bool is_sphere = false;
    double lam_0 = 0.0;
    double phi_0 = 0.0;
