    int zone = 0;
    bool south = false;
    std::string title = "";
    std::string category = "";
    std::string note = "";
    std::string orig_proj_str = "";
    bool inv_in_proj = false;
    bool is_angular_output = false;
};

// Check if projection name is valid
inline bool is_known_proj(const std::string& name) {
    static const std::vector<std::string> known = {
        "adams_hemi", "adams_ws1", "adams_ws2", "aea", "aeqd", "affine", "airy", "aitoff",
