        "horner", "igh", "igh_o", "imoll", "imoll_o", "imw_p", "isea", "kav5", "kav7",
        "krovak", "labrd", "laea", "lagrng", "larr", "lask", "lonlat", "latlon",
        "longlat", "lcc", "lcca", "leac", "lee_os", "loxim", "lsat", "mbt_s", "mbt_fps",
        "mbtfpp", "mbtfpq", "mbtfps", "merc", "mil_os", "mill", "misrsom", "mod_krovak",
        "moll", "molobadekas", "molodensky", "murd1", "murd2", "murd3", "natearth",
        "natearth2", "nell", "nell_h", "nicol", "nsper", "nzmg", "noop", "ob_tran",
        "ocea", "oea", "omerc", "ortel", "ortho", "pconic", "patterson", "peirce_q",
        "pipeline", "poly", "pop", "push", "putp1", "putp2", "putp3", "putp3p",
        "putp4p", "putp5", "putp5p", "putp6", "putp6p", "qua_aut", "qsc", "robin",
        "rouss", "rpoly", "s2", "sch", "set", "sinu", "som", "somerc", "spilhaus",
        "stere", "sterea", "gstmerc", "tcc", "tcea", "times", "tinshift", "tissot",
        "tmerc", "tobmerc", "topocentric", "tpeqd", "tpers", "unitconvert", "ups",
        "urm5", "urmfps", "utm", "vandg", "vandg2", "vandg3", "vandg4", "vertoffset",
