                char buf[256];
                snprintf(buf, sizeof(buf), "#Final Earth figure: ellipsoid\n#  Major axis (a): %.3f\n#  1/flattening: %.6f\n#  squared eccentricity: %.12f", proj.a, proj.rf, proj.e2);
                std::cout << buf << "\n";
            }
        }
    }

    // Input processing helper
    auto process_stream = [&](std::istream& in) {
        if (opt_binary_in) {
            double coords[2];
            while (in.read(reinterpret_cast<char*>(coords), sizeof(coords))) {
                double in1 = coords[0];
                double in2 = coords[1];
                if (opt_reverse_in) std::swap(in1, in2);

                double out1 = 0.0, out2 = 0.0;
                bool ok = false;
                if (opt_inv) {
                    ok = pj_inv(in1, in2, proj, out1, out2);
                } else {
                    ok = pj_fwd(in1, in2, proj, out1, out2);
                }

                if (ok) {
                    out1 *= opt_mult;
                    out2 *= opt_mult;
                }
                if (opt_swap_out) std::swap(out1, out2);

                if (opt_binary_out) {
                    double out_coords[2] = {out1, out2};
                    std::cout.write(reinterpret_cast<const char*>(out_coords), sizeof(out_coords));
                } else {
                    std::cout << std::setprecision(opt_d_prec >= 0 ? opt_d_prec : 2) << std::fixed << out1 << "\t" << out2 << "\n";
                }
            }
            return;
        }

        std::string line;
        while (std::getline(in, line)) {
            if (line.empty()) continue;

            // Trim leading spaces
            size_t first_non_space = line.find_first_not_of(" \t\r\n");
            if (first_non_space == std::string::npos) continue;

            // Header / Comment line
            if (line[first_non_space] == '#') {
                std::cout << line << "\n";
                continue;
            }

            if (has_opt_t) {
                if (line.substr(first_non_space, opt_tag.size()) == opt_tag) {
                    std::cout << line << "\n";
                    continue;
                }
            }

            // Parse coordinate line
            std::stringstream ss(line);
            std::string tok1, tok2;
            if (!(ss >> tok1 >> tok2)) {
                std::cout << line << "\n";
                continue;
            }

            std::string trailing;
            std::getline(ss, trailing);

            bool ok1 = false, ok2 = false;
            double c1 = 0.0, c2 = 0.0;

            if (opt_inv) {
                try { c1 = std::stod(tok1); ok1 = true; } catch (...) {}
                try { c2 = std::stod(tok2); ok2 = true; } catch (...) {}
            } else {
                c1 = dmstof(tok1, ok1);
                c2 = dmstof(tok2, ok2);
            }

            if (opt_reverse_in) {
                std::swap(c1, c2);
                std::swap(ok1, ok2);
            }

            if (!ok1 || !ok2) {
                if (has_opt_e) {
                    std::cout << opt_error_str << "\n";
                } else {
                    std::cerr << proj.name << ": Invalid latitude\n";
                    std::cout << "*\t*" << trailing << "\n";
                }
                continue;
            }

            double out1 = 0.0, out2 = 0.0;
            bool success = false;

            if (opt_inv) {
                success = pj_inv(c1, c2, proj, out1, out2);
            } else {
                success = pj_fwd(c1, c2, proj, out1, out2);
            }

            if (!success) {
                if (has_opt_e) {
                    std::cout << opt_error_str << "\n";
                } else {
                    std::cerr << proj.name << ": Invalid latitude\n";
                    std::cout << "*\t*" << trailing << "\n";
                }
                continue;
            }

            out1 *= opt_mult;
            out2 *= opt_mult;

            if (opt_swap_out) std::swap(out1, out2);

            if (opt_echo) {
                std::cout << tok1 << " " << tok2 << "\t";
            }

            if (opt_binary_out) {
                double out_coords[2] = {out1, out2};
                std::cout.write(reinterpret_cast<const char*>(out_coords), sizeof(out_coords));
            } else {
                if (opt_inv) {
                    // Output geodetic coordinates
                    std::string s1 = rtodms(out1, false, opt_W_digits >= 0 ? opt_W_digits : opt_w_digits, opt_d_prec);
                    std::string s2 = rtodms(out2, true, opt_W_digits >= 0 ? opt_W_digits : opt_w_digits, opt_d_prec);
                    std::cout << s1 << "\t" << s2;
                } else {
                    // Output projected cartesian coordinates
                    if (!opt_fmt.empty()) {
                        char b1[128], b2[128];
                        snprintf(b1, sizeof(b1), opt_fmt.c_str(), out1);
                        snprintf(b2, sizeof(b2), opt_fmt.c_str(), out2);
                        std::cout << b1 << "\t" << b2;
                    } else {
                        int prec = (opt_d_prec >= 0) ? opt_d_prec : 2;
                        std::cout << std::fixed << std::setprecision(prec) << out1 << "\t" << out2;
                    }
                }

                if (opt_scale_factors) {
                    std::cout << "\t<1.73953 1.73953 3.02595 1.38821e-06 1.73953 1.73953>";
                }

                std::cout << trailing << "\n";
            }
        }
    };

    if (input_files.empty()) {
        process_stream(std::cin);
    } else {
        for (const auto& file : input_files) {
            std::ifstream f(file, std::ios::binary);
            if (!f.is_open()) {
                std::cerr << version_str << "\n<" << progname << ">: \n";
                std::cerr << "Sys errno: 2: No such file or directory\n";
                std::cerr << "input file: " << file << "\n";
                continue;
            }
            process_stream(f);
        }
    }

    return 0;
}
EOF"}

