#include <iomanip>

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

#define DEG_TO_RAD (M_PI / 180.0)
#define RAD_TO_DEG (180.0 / M_PI)

inline double dmstof(const std::string& str, bool& ok) {
    ok = false;
    if (str.empty()) return 0.0;

    std::string s = str;
    size_t start = s.find_first_not_of(" \t\r\n");
    if (start == std::string::npos) return 0.0;
    size_t end = s.find_last_not_of(" \t\r\n");
    s = s.substr(start, end - start + 1);

    int sign = 1;
    if (s[0] == '-') {
        sign = -1;
        s = s.substr(1);
    } else if (s[0] == '+') {
        s = s.substr(1);
    }

    if (!s.empty()) {
        char last = std::toupper((unsigned char)s.back());
        if (last == 'N' || last == 'E') {
            s.pop_back();
        } else if (last == 'S' || last == 'W') {
            s.pop_back();
            sign = -sign;
        }
    }

    double deg = 0.0, min = 0.0, sec = 0.0;
    bool parsed = false;

    size_t d_pos = s.find_first_of("dD");
    size_t r_pos = s.find_first_of("rR");
    if (r_pos != std::string::npos) {
        try {
            double rad = std::stod(s.substr(0, r_pos));
            ok = true;
            return rad * sign;
        } catch (...) {
            return 0.0;
        }
    }

    if (d_pos != std::string::npos) {
        try {
            std::string d_str = s.substr(0, d_pos);
            deg = d_str.empty() ? 0.0 : std::stod(d_str);
            std::string rem = s.substr(d_pos + 1);
            size_t m_pos = rem.find('\'');
            if (m_pos != std::string::npos) {
                std::string m_str = rem.substr(0, m_pos);
                min = m_str.empty() ? 0.0 : std::stod(m_str);
                std::string s_rem = rem.substr(m_pos + 1);
                size_t s_pos = s_rem.find('\"');
                if (s_pos != std::string::npos) {
                    std::string s_str = s_rem.substr(0, s_pos);
                    sec = s_str.empty() ? 0.0 : std::stod(s_str);
                } else if (!s_rem.empty()) {
                    sec = std::stod(s_rem);
                }
            } else if (!rem.empty()) {
                size_t s_pos = rem.find('\"');
                if (s_pos != std::string::npos) {
                    sec = std::stod(rem.substr(0, s_pos));
                } else {
                    min = std::stod(rem);
                }
            }
            parsed = true;
        } catch (...) {
            parsed = false;
        }
    } else {
        try {
            char* endptr = nullptr;
            deg = std::strtod(s.c_str(), &endptr);
            if (endptr != s.c_str()) {
                parsed = true;
            }
        } catch (...) {
            parsed = false;
        }
    }

    if (parsed) {
        ok = true;
        double val = deg + min / 60.0 + sec / 3600.0;
        return val * sign * DEG_TO_RAD;
    }
    return 0.0;
}

inline std::string rtodms(double rad, bool is_lat, int w_digits, int d_prec) {
    if (d_prec >= 0) {
        double deg = rad * RAD_TO_DEG;
        char buf[64];
        snprintf(buf, sizeof(buf), "%.*f", d_prec, deg);
        return std::string(buf);
    }

    double deg_val = std::abs(rad * RAD_TO_DEG);
    char suf = is_lat ? (rad < 0 ? 'S' : 'N') : (rad < 0 ? 'W' : 'E');

    int d = (int)std::floor(deg_val);
    double rem_m = (deg_val - d) * 60.0;
    int m = (int)std::floor(rem_m);
    double s = (rem_m - m) * 60.0;

    int num_sec_decimals = (w_digits >= 0) ? w_digits : 3;
    double scale = std::pow(10.0, num_sec_decimals);
    s = std::round(s * scale) / scale;
    if (s >= 60.0) {
        s -= 60.0;
        m += 1;
        if (m >= 60) {
            m -= 60;
            d += 1;
        }
    }

    if (w_digits >= 0) {
        char buf[128];
        if (w_digits == 0) {
            snprintf(buf, sizeof(buf), "%dd%02d'%02d\"%c", d, m, (int)std::round(s), suf);
        } else {
            snprintf(buf, sizeof(buf), "%dd%02d'%0*.*f\"%c", d, m, w_digits + 3, w_digits, s, suf);
        }
        return std::string(buf);
    }

    if (std::abs(s) < 1e-6 && m == 0) {
        return std::to_string(d) + "d" + suf;
    }
    if (std::abs(s) < 1e-6) {
        return std::to_string(d) + "d" + std::to_string(m) + "'" + suf;
    }

    char buf[128];
    if (std::abs(s - std::round(s)) < 1e-4) {
        snprintf(buf, sizeof(buf), "%dd%d'%d\"%c", d, m, (int)std::round(s), suf);
    } else {
        snprintf(buf, sizeof(buf), "%dd%d'%.3f\"%c", d, m, s, suf);
    }
    return std::string(buf);
}

#endif
EOF"}

