        else if (key == "ellps") { ellps_name = val; custom_ellps = true; }
        else if (key == "a") proj.a = std::stod(val);
        else if (key == "b") proj.b = std::stod(val);
        else if (key == "rf") { proj.rf = std::stod(val); }
        else if (key == "f") { proj.rf = 1.0 / std::stod(val); }
        else if (key == "lon_0") {
            bool ok = false;
            proj.lam_0 = dmstof(val, ok);
        } else if (key == "lat_0") {
            bool ok = false;
            proj.phi_0 = dmstof(val, ok);
        } else if (key == "x_0") proj.x_0 = std::stod(val);
        else if (key == "y_0") proj.y_0 = std::stod(val);
        else if (key == "k_0" || key == "k") proj.k_0 = std::stod(val);
        else if (key == "lat_1") { bool ok; proj.lat_1 = dmstof(val, ok); }
        else if (key == "lat_2") { bool ok; proj.lat_2 = dmstof(val, ok); }
        else if (key == "lat_ts") { bool ok; proj.lat_ts = dmstof(val, ok); }
        else if (key == "units") {
            double u_factor = 1.0;
            if (find_unit(val, u_factor)) proj.to_meter = u_factor;
        } else if (key == "to_meter") proj.to_meter = std::stod(val);
        else if (key == "zone") proj.zone = std::stoi(val);
