        std::cerr << "cause: Unknown error (code 2)\n";
        std::cerr << "program abnormally terminated\n";
        return 3;
    }

    if (!is_known_proj(proj.name)) {
        std::cerr << "proj_create: Error 1027 (Invalid value for an argument): Unknown projection\n";
        std::cerr << version_str << "\n<" << progname << ">: \n";
        std::cerr << "projection initialization failure\n";
        std::cerr << "cause: Invalid value for an argument\n";
        std::cerr << "program abnormally terminated\n";
        return 3;
    }

    if (proj.name == "longlat" || proj.name == "latlon" || proj.name == "lonlat" || proj.name == "geogoffset") {
        std::cerr << version_str << "\n<" << progname << ">: \n";
        std::cerr << "can't initialize operations that produce angular output coordinates\n";
        std::cerr << "program abnormally terminated\n";
        return 3;
