        "urm5", "urmfps", "utm", "vandg", "vandg2", "vandg3", "vandg4", "vertoffset",
        "vitk1", "vgridshift", "wag1", "wag2", "wag3", "wag4", "wag5", "wag6", "wag7",
        "webmerc", "weren", "wink1", "wink2", "wintri", "xyzgridshift"
    };
    return std::find(known.begin(), known.end(), name) != known.end();
}

inline void set_proj_metadata(ProjParams& p) {
    if (p.name == "merc") {
        p.title = "Mercator"; p.category = "Cyl, Sph&Ell"; p.note = "lat_ts=";
    } else if (p.name == "tmerc" || p.name == "etmerc") {
        p.title = "Transverse Mercator"; p.category = "Cyl, Sph&Ell"; p.note = "approx";
    } else if (p.name == "utm") {
        p.title = "Universal Transverse Mercator (UTM)"; p.category = "Cyl, Ell"; p.note = "zone= south approx";
    } else if (p.name == "lcc") {
        p.title = "Lambert Conformal Conic"; p.category = "Conic, Sph&Ell"; p.note = "lat_1= and lat_2= or lat_0, k_0=";
    } else if (p.name == "aea") {
        p.title = "Albers Equal Area"; p.category = "Conic, Sph&Ell"; p.note = "lat_1= and lat_2=";
    } else if (p.name == "laea") {
        p.title = "Lambert Azimuthal Equal Area"; p.category = "Azi, Sph&Ell"; p.note = "";
    } else if (p.name == "aeqd") {
        p.title = "Azimuthal Equidistant"; p.category = "Azi, Sph&Ell"; p.note = "lat_0 guam";
    } else if (p.name == "eqc") {
        p.title = "Equidistant Cylindrical (Plate Carree)"; p.category = "Cyl, Sph"; p.note = "lat_ts=";
    } else if (p.name == "cea") {
        p.title = "Equal Area Cylindrical"; p.category = "Cyl, Sph&Ell"; p.note = "lat_ts=";
    } else if (p.name == "moll") {
        p.title = "Mollweide"; p.category = "Cyl, Sph"; p.note = "";
    } else if (p.name == "robin") {
        p.title = "Robinson"; p.category = "Pcyl, Sph"; p.note = "";
    } else if (p.name == "sinu") {
        p.title = "Sinusoidal (Sanson-Flamsteed)"; p.category = "Pcyl, Sph&Ell"; p.note = "";
    } else if (p.name == "mill") {
        p.title = "Miller Cylindrical"; p.category = "Cyl, Sph"; p.note = "";
    } else if (p.name == "gall") {
        p.title = "Gall (Gall Stereographic)"; p.category = "Cyl, Sph"; p.note = "";
    } else if (p.name == "wintri" || p.name == "wink3") {
        p.title = "Winkel Tripel"; p.category = "Azn, Sph"; p.note = "lat_1=";
    } else {
        p.title = p.name; p.category = "Misc Sph"; p.note = "";
    }
}

inline double pj_mlfn(double phi, double e2, double a) {
    if (e2 == 0.0) return a * phi;
    double f = 1.0 - std::sqrt(1.0 - e2);
    double b = a * (1.0 - f);
    double n = (a - b) / (a + b);
    double n2 = n * n;
    double n3 = n2 * n;
    double n4 = n3 * n;

    double A0 = 1.0 + n2 / 4.0 + n4 / 64.0;
    double A2 = 1.5 * (n - n3 / 8.0);
    double A4 = 0.9375 * (n2 - n4 / 4.0);
    double A6 = (35.0 / 48.0) * n3;
    double A8 = (315.0 / 512.0) * n4;

    double val = A0 * phi - A2 * std::sin(2.0 * phi) + A4 * std::sin(4.0 * phi) - A6 * std::sin(6.0 * phi) + A8 * std::sin(8.0 * phi);
    return (a / (1.0 + n)) * val;
}

inline double pj_inv_mlfn(double M, double e2, double a) {
    if (e2 == 0.0) return M / a;
    double phi = M / a;
    for (int i = 0; i < 15; ++i) {
        double m = pj_mlfn(phi, e2, a);
        double dphi = (M - m) / a;
        phi += dphi;
        if (std::abs(dphi) < 1e-12) break;
    }
    return phi;
}

inline double pj_qsfn(double sinphi, double e) {
    if (e == 0.0) return 2.0 * sinphi;
    double con = e * sinphi;
    return (1.0 - e * e) * (sinphi / (1.0 - con * con) - (0.5 / e) * std::log((1.0 - con) / (1.0 + con)));
}

// Forward projection
inline bool pj_fwd(double lam, double phi, const ProjParams& p, double& x, double& y) {
    if (std::abs(phi) > M_PI_2 + 1e-9) return false;
    double dlam = lam - p.lam_0;

    if (p.name == "merc") {
        x = p.a * p.k_0 * dlam;
        if (p.is_sphere) {
            y = p.a * p.k_0 * std::log(std::tan(M_PI_4 + phi / 2.0));
        } else {
            double sinphi = std::sin(phi);
            double con = p.e * sinphi;
            if (std::abs(sinphi) >= 1.0) return false;
            con = std::pow((1.0 - con) / (1.0 + con), 0.5 * p.e);
            y = p.a * p.k_0 * std::log(std::tan(M_PI_4 + phi / 2.0) * con);
        }
    } else if (p.name == "tmerc" || p.name == "etmerc" || p.name == "utm") {
        double k0 = p.k_0;
        if (p.name == "utm") k0 = 0.9996;

        if (p.is_sphere) {
            double B = std::cos(phi) * std::sin(dlam);
            if (std::abs(std::abs(B) - 1.0) < 1e-12) return false;
            x = 0.5 * p.a * k0 * std::log((1.0 + B) / (1.0 - B));
            double y_val = std::atan2(std::tan(phi), std::cos(dlam)) - p.phi_0;
            y = p.a * k0 * y_val;
        } else {
            double sinphi = std::sin(phi);
            double cosphi = std::cos(phi);
            double tanphi = std::tan(phi);

            double N = p.a / std::sqrt(1.0 - p.e2 * sinphi * sinphi);
            double T = tanphi * tanphi;
            double C = (p.e2 / (1.0 - p.e2)) * cosphi * cosphi;
            double A = dlam * cosphi;
            double M = pj_mlfn(phi, p.e2, p.a);
            double M0 = pj_mlfn(p.phi_0, p.e2, p.a);

            double A2 = A * A, A3 = A2 * A, A4 = A2 * A2, A5 = A4 * A, A6 = A3 * A3;

            x = k0 * N * (A + (1.0 - T + C) * A3 / 6.0 + (5.0 - 18.0 * T + T * T + 72.0 * C) * A5 / 120.0);
            y = k0 * (M - M0 + N * tanphi * (A2 / 2.0 + (5.0 - T + 9.0 * C + 4.0 * C * C) * A4 / 24.0 + (61.0 - 58.0 * T + T * T) * A6 / 720.0));
        }
    } else if (p.name == "eqc") {
        x = p.a * dlam * std::cos(p.phi_0);
        y = pj_mlfn(phi, p.e2, p.a) - pj_mlfn(p.phi_0, p.e2, p.a);
    } else if (p.name == "cea") {
        x = p.a * dlam * std::cos(p.lat_ts);
        if (p.is_sphere) {
            y = p.a * std::sin(phi) / std::cos(p.lat_ts);
        } else {
            double q = pj_qsfn(std::sin(phi), p.e);
            y = p.a * q / (2.0 * std::cos(p.lat_ts));
        }
    } else if (p.name == "mill") {
        x = p.a * dlam;
        y = p.a * 1.25 * std::log(std::tan(M_PI_4 + 0.4 * phi));
    } else if (p.name == "gall") {
        x = p.a * dlam / std::sqrt(2.0);
        y = p.a * (1.0 + 1.0 / std::sqrt(2.0)) * std::tan(phi / 2.0);
    } else if (p.name == "sinu") {
        if (p.is_sphere) {
            x = p.a * dlam * std::cos(phi);
        } else {
            double sinphi = std::sin(phi);
            double N = p.a / std::sqrt(1.0 - p.e2 * sinphi * sinphi);
            x = N * dlam * std::cos(phi);
        }
        y = pj_mlfn(phi, p.e2, p.a);
    } else if (p.name == "moll") {
        double theta = phi;
        for (int i = 0; i < 20; ++i) {
            double dtheta = -(2.0 * theta + std::sin(2.0 * theta) - M_PI * std::sin(phi)) / (2.0 + 2.0 * std::cos(2.0 * theta));
            theta += dtheta;
            if (std::abs(dtheta) < 1e-12) break;
        }
        x = (2.0 * std::sqrt(2.0) / M_PI) * p.a * dlam * std::cos(theta);
        y = std::sqrt(2.0) * p.a * std::sin(theta);
    } else if (p.name == "robin") {
        static const double PR_X[19] = {1.0000, 0.9986, 0.9954, 0.9900, 0.9822, 0.9730, 0.9600, 0.9427, 0.9216, 0.8962, 0.8679, 0.8350, 0.7986, 0.7597, 0.7186, 0.6732, 0.6213, 0.5722, 0.5322};
        static const double PR_Y[19] = {0.0000, 0.0620, 0.1240, 0.1860, 0.2480, 0.3100, 0.3720, 0.4340, 0.4958, 0.5571, 0.6176, 0.6769, 0.7346, 0.7903, 0.8435, 0.8936, 0.9394, 0.9761, 1.0000};

        double deg = std::abs(phi) * RAD_TO_DEG;
        int idx = (int)std::floor(deg / 5.0);
        if (idx >= 18) idx = 17;
        double rem = (deg - idx * 5.0) / 5.0;

        double rx = PR_X[idx] + rem * (PR_X[idx + 1] - PR_X[idx]);
        double ry = PR_Y[idx] + rem * (PR_Y[idx + 1] - PR_Y[idx]);

        x = 0.8487 * p.a * dlam * rx;
        y = 1.3523001325 * p.a * (phi < 0 ? -ry : ry);
    } else if (p.name == "wintri" || p.name == "wink3") {
        double lat1 = (p.lat_1 != 0.0) ? p.lat_1 : std::acos(2.0 / M_PI);
        double cosphi = std::cos(phi);
        double sinc = std::sin(dlam / 2.0) * cosphi;
        double cosc = std::cos(phi) * std::cos(dlam / 2.0);
        double c = std::acos(std::clamp(cosc, -1.0, 1.0));
        double sinc_c = (c == 0.0) ? 1.0 : (c / std::sin(c));

        double x1 = p.a * 2.0 * sinc * sinc_c;
        double y1 = p.a * c * std::sin(phi) / (c == 0.0 ? 1.0 : std::sin(c));
        double x2 = p.a * dlam * std::cos(lat1);
        double y2 = p.a * phi;
        x = 0.5 * (x1 + x2);
        y = 0.5 * (y1 + y2);
    } else if (p.name == "ortho") {
        x = p.a * std::cos(phi) * std::sin(dlam);
        y = p.a * (std::cos(p.phi_0) * std::sin(phi) - std::sin(p.phi_0) * std::cos(phi) * std::cos(dlam));
    } else if (p.name == "gnom") {
        double cos_c = std::sin(p.phi_0) * std::sin(phi) + std::cos(p.phi_0) * std::cos(phi) * std::cos(dlam);
        if (cos_c <= 0.0) return false;
        x = p.a * std::cos(phi) * std::sin(dlam) / cos_c;
        y = p.a * (std::cos(p.phi_0) * std::sin(phi) - std::sin(p.phi_0) * std::cos(phi) * std::cos(dlam)) / cos_c;
    } else if (p.name == "aeqd") {
        double cos_c = std::sin(p.phi_0) * std::sin(phi) + std::cos(p.phi_0) * std::cos(phi) * std::cos(dlam);
        double c = std::acos(std::clamp(cos_c, -1.0, 1.0));
        double k = (c == 0.0) ? 1.0 : (c / std::sin(c));
        x = p.a * k * std::cos(phi) * std::sin(dlam);
        y = p.a * k * (std::cos(p.phi_0) * std::sin(phi) - std::sin(p.phi_0) * std::cos(phi) * std::cos(dlam));
    } else if (p.name == "laea") {
        double g = std::sin(p.phi_0) * std::sin(phi) + std::cos(p.phi_0) * std::cos(phi) * std::cos(dlam);
        if (g < -0.9999999) return false;
        double k = std::sqrt(2.0 / (1.0 + g));
        x = p.a * k * std::cos(phi) * std::sin(dlam);
        y = p.a * k * (std::cos(p.phi_0) * std::sin(phi) - std::sin(p.phi_0) * std::cos(phi) * std::cos(dlam));
    } else if (p.name == "lcc") {
        double lat1 = (p.lat_1 != 0.0) ? p.lat_1 : p.phi_0;
        double lat2 = (p.lat_2 != 0.0) ? p.lat_2 : lat1;
        double n = (lat1 == lat2) ? std::sin(lat1) : std::log(std::cos(lat1) / std::cos(lat2)) / std::log(std::tan(M_PI_4 + lat2 / 2.0) / std::tan(M_PI_4 + lat1 / 2.0));
        if (n == 0.0) n = 1e-9;
        double F = (std::cos(lat1) * std::pow(std::tan(M_PI_4 + lat1 / 2.0), n)) / n;
        double rho0 = p.a * F / std::pow(std::tan(M_PI_4 + p.phi_0 / 2.0), n);
        double rho = p.a * F / std::pow(std::tan(M_PI_4 + phi / 2.0), n);
        double theta = n * dlam;
        x = rho * std::sin(theta);
        y = rho0 - rho * std::cos(theta);
    } else if (p.name == "aea") {
        double lat1 = (p.lat_1 != 0.0) ? p.lat_1 : p.phi_0;
        double lat2 = (p.lat_2 != 0.0) ? p.lat_2 : lat1;
        double n = 0.5 * (std::sin(lat1) + std::sin(lat2));
        if (n == 0.0) n = 1e-9;
        double C = std::pow(std::cos(lat1), 2) + 2.0 * n * std::sin(lat1);
        double rho0 = p.a * std::sqrt(C - 2.0 * n * std::sin(p.phi_0)) / n;
        double rho = p.a * std::sqrt(C - 2.0 * n * std::sin(phi)) / n;
        double theta = n * dlam;
        x = rho * std::sin(theta);
        y = rho0 - rho * std::cos(theta);
    } else {
        x = p.a * dlam * std::cos(p.phi_0);
        y = p.a * (phi - p.phi_0);
    }

    x = (x + p.x_0) / p.to_meter;
    y = (y + p.y_0) / p.to_meter;
    return true;
}

// Inverse projection
inline bool pj_inv(double x, double y, const ProjParams& p, double& lam, double& phi) {
    double px = x * p.to_meter - p.x_0;
    double py = y * p.to_meter - p.y_0;

    if (p.name == "merc") {
        lam = p.lam_0 + px / (p.a * p.k_0);
        if (p.is_sphere) {
            phi = 2.0 * std::atan(std::exp(py / (p.a * p.k_0))) - M_PI_2;
        } else {
            double ts = std::exp(-py / (p.a * p.k_0));
            double phi_i = M_PI_2 - 2.0 * std::atan(ts);
            for (int i = 0; i < 15; ++i) {
                double con = p.e * std::sin(phi_i);
                double dphi = M_PI_2 - 2.0 * std::atan(ts * std::pow((1.0 - con) / (1.0 + con), 0.5 * p.e)) - phi_i;
                phi_i += dphi;
                if (std::abs(dphi) < 1e-12) break;
            }
            phi = phi_i;
        }
    } else if (p.name == "tmerc" || p.name == "etmerc" || p.name == "utm") {
        double k0 = p.k_0;
        if (p.name == "utm") k0 = 0.9996;
        double D = py / (p.a * k0) + p.phi_0;
        phi = std::asin(std::sin(D) / std::cosh(px / (p.a * k0)));
        lam = p.lam_0 + std::atan(std::sinh(px / (p.a * k0)) / std::cos(D));
    } else if (p.name == "eqc") {
        lam = p.lam_0 + px / (p.a * std::cos(p.phi_0));
        phi = pj_inv_mlfn(py + pj_mlfn(p.phi_0, p.e2, p.a), p.e2, p.a);
    } else if (p.name == "cea") {
        lam = p.lam_0 + px / (p.a * std::cos(p.lat_ts));
        phi = std::asin(std::clamp((py / p.a) * std::cos(p.lat_ts), -1.0, 1.0));
    } else if (p.name == "mill") {
        lam = p.lam_0 + px / p.a;
        phi = 2.5 * (std::atan(std::exp(0.8 * py / p.a)) - M_PI_4);
    } else if (p.name == "gall") {
        lam = p.lam_0 + px * std::sqrt(2.0) / p.a;
        phi = 2.0 * std::atan(py / (p.a * (1.0 + 1.0 / std::sqrt(2.0))));
    } else if (p.name == "sinu") {
        phi = pj_inv_mlfn(py, p.e2, p.a);
        double cosphi = std::cos(phi);
        if (std::abs(cosphi) < 1e-12) lam = p.lam_0;
        else lam = p.lam_0 + px / (p.a * cosphi);
    } else if (p.name == "moll") {
        double theta = std::asin(std::clamp(py / (std::sqrt(2.0) * p.a), -1.0, 1.0));
        phi = std::asin(std::clamp((2.0 * theta + std::sin(2.0 * theta)) / M_PI, -1.0, 1.0));
        double costheta = std::cos(theta);
        if (std::abs(costheta) < 1e-12) lam = p.lam_0;
        else lam = p.lam_0 + px / ((2.0 * std::sqrt(2.0) / M_PI) * p.a * costheta);
    } else {
        lam = p.lam_0 + px / (p.a * std::cos(p.phi_0));
        phi = p.phi_0 + py / p.a;
    }

    return true;
}

